style.css:
body::before {
    content: "";
    position: fixed;
    top: 100px;       
    left: 0;
    width: 120px;     
    height: 400px;    
    background-image: url("https://i.postimg.cc/VNJFYDjs/reklama-3.png");
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 9999;
}


body::after {
    content: "";
    position: fixed;
    top: 100px;
    right: 0;
    width: 120px;
    height: 400px;
    background-image: url("https://i.postimg.cc/Fs08vs9f/reklama-1.png");
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 9999;
}
